import java.util.*;
import java.io.*;

public class Div680 {
    private static int N, MOD, CENTER;
    private static int[][][] CACHE;

    public static void main(String[] args) throws Exception {
        BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
        String[] params = in.readLine().split(" ");
        N = Integer.parseInt(params[0]);
        MOD = Integer.parseInt(params[1]);
        CENTER = N * (N - 1);
        CACHE = new int[2][N][2 * CENTER + 1];
        for (int[][] layer : CACHE) for (int[] row : layer) Arrays.fill(row, -1);
        System.out.println(countPairs(0));
        in.close();
    }

    private static int countPairs(int position) {
        if (position == N - 1) return 0;
        long res = ((long)(N - position) * countPairs(position + 1)) % MOD;
        for (int left = 0; left < N - position; left++) {
            for (int right = left + 1; right < N - position; right++) {
                res = (res + solve(1, position + 1, left - right)) % MOD;
            }
        }
        return (int)res;
    }

    private static int solve(int flag, int idx, int delta) {
        if (idx == N) return delta > 0 ? 1 : 0;
        int index = delta + CENTER;
        if (CACHE[flag][idx][index] != -1) return CACHE[flag][idx][index];
        int available = N - idx;
        long total = 0;
        outer:
        for (int a = 0; a < available; a++) {
            for (int b = (flag == 1 ? 0 : a); b < available; b++) {
                total = (total + solve(flag | ((a < b) ? 1 : 0), idx + 1, delta + a - b)) % MOD;
            }
        }
        return CACHE[flag][idx][index] = (int)total;
    }

    private static long gcd(long x, long y) {
        return x == 0 ? y : gcd(y % x, x);
    }

    static class Scanner {
        private BufferedReader reader;
        private StringTokenizer tokens;

        Scanner(InputStream stream) { reader = new BufferedReader(new InputStreamReader(stream)); }
        Scanner(FileReader fr) { reader = new BufferedReader(fr); }

        String next() throws IOException {
            while (tokens == null || !tokens.hasMoreTokens()) tokens = new StringTokenizer(reader.readLine());
            return tokens.nextToken();
        }

        int nextInt() throws IOException { return Integer.parseInt(next()); }
        long nextLong() throws IOException { return Long.parseLong(next()); }
        String nextLine() throws IOException { return reader.readLine(); }
        double nextDouble() throws IOException {
            String token = next();
            boolean neg = token.charAt(0) == '-';
            if (neg) token = token.substring(1);
            double value = 0, scale = 1;
            boolean fraction = false;
            for (char ch : token.toCharArray()) {
                if (ch == '.') { fraction = true; continue; }
                value = value * 10 + (ch - '0');
                if (fraction) scale *= 10;
            }
            return (value / scale) * (neg ? -1 : 1);
        }
        boolean ready() throws IOException { return reader.ready(); }
    }
}
